#define main ReadOnlyPoleDiagnosticUnusedMain
#include "diagnose_scri_pole.cpp"
#undef main
#include "mesh/cubed_sphere/centered_surface_atlas.hpp"
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{
 if(argc!=4)throw std::runtime_error("checkpoint source_tag output.csv");auto snap=cubed_sphere::CompositeCheckpoint::Read(argv[1],argv[2]);cubed_sphere::CompositeDifference g(snap.mesh,4,snap.radial_interface_stencils);if(g.active.size()>50000||g.n!=6)throw std::runtime_error("bounded N6 <=50000");cubed_sphere::ScriSurface surface(g,22,7);cubed_sphere::CenteredSurfaceAtlas atlas(g.mesh,22);if(atlas.values.size()!=snap.boundary_fields.size())throw std::runtime_error("surface layout");atlas.values=snap.boundary_fields;V padded(22*g.count,0);for(size_t p=0;p<g.active.size();++p)for(int v=0;v<22;++v)padded[v*g.count+g.active[p]]=snap.fields[22*p+v];
 std::ofstream out(argv[3]);out<<std::setprecision(17)<<"row,face,j,k,x,y,z";const char*names[]={"chi","Khat","Theta","alpha","Axx","Axy","Axz","Ayy","Ayz","Azz","LambdaX","LambdaY","LambdaZ"};for(auto mode:{"withinface","crossface_all","crossface_metric"})for(auto name:names)out<<','<<mode<<'_'<<name;out<<'\n';Real value_error=0,normal_error=0;
 for(size_t p=0;p<surface.rows.size();++p){const auto &row=surface.rows[p];const auto &x=row.geometry.x;const auto sample=surface.Sample(p,padded,snap.boundary_fields,22);const Real q[3]={1,(row.j+.5)/g.n,(row.k+.5)/g.n};const auto centered=atlas.At(row.block,q);out<<p<<','<<g.mesh.blocks[row.block].face<<','<<row.j<<','<<row.k<<','<<x[0]<<','<<x[1]<<','<<x[2];for(int f=0;f<22;++f){value_error=std::max(value_error,std::abs(centered.value[f]-sample.value[f]));Real nd=0;for(int i=0;i<3;++i)nd+=x[i]*centered.d[f][i];normal_error=std::max(normal_error,std::abs(nd));}
 for(int mode=0;mode<3;++mode){auto d=sample.d;if(mode)for(int f=0;f<22;++f){if(mode==2&&(f<1||f>6))continue;Real nd=0;for(int i=0;i<3;++i)nd+=x[i]*sample.d[f][i];for(int i=0;i<3;++i)d[f][i]=x[i]*nd+centered.d[f][i];}auto u=h::UnpackComposite(x,sample.value,d,sample.dd,true,0,2);Real beta[3];if(!h::FixedAngleScriShift(h::Geometry(u.metric),Real(1),u.chi.value,x,beta))throw std::runtime_error("null datum failed");for(int i=0;i<3;++i)u.beta.value[i]=beta[i];for(auto v:Poles(u,x))out<<','<<v;}out<<'\n';}
 std::cout<<std::setprecision(17)<<"{\"cells\":"<<g.active.size()<<",\"surface_rows\":"<<surface.rows.size()<<",\"time\":"<<snap.dt*snap.step<<",\"angular_atlas_value_error\":"<<value_error<<",\"atlas_normal_derivative_max\":"<<normal_error<<",\"values_and_original_radial_first_derivatives_retained\":true,\"second_jets_not_used_by_pole\":true,\"no_solve_or_evolution\":true}\n";if(value_error>1e-12||normal_error>1e-12)throw std::runtime_error("atlas pole comparison consistency");
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=2;}Kokkos::finalize();return code;}
